  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:kamakura:kotoku-in-great-buddha-of-kamakura', 'Kanto', 'Kanagawa', 'Kamakura', 'JP', 'Kotoku-in (Great Buddha of Kamakura)', 'Temple', 'A Buddhist temple of the Jodo sect renowned for its colossal open-air bronze statue of Amida-butsu, commonly known as the Great Buddha of Kamakura, which has stood since the 13th century.', '[{"text": "Visitors can pay a small fee to enter the interior of the hollow bronze Great Buddha statue.", "source_url": "https://www.kotoku-in.jp/en/index.php"}, {"text": "Refrain from flying drones on the grounds or using selfie sticks inside the statue.", "source_url": "https://www.kotoku-in.jp/en/index.php"}]'::jsonb, '8:00 AM - 5:30 PM (April to September), 8:00 AM - 5:00 PM (October to March)', 'known', 'Hase Station (Enoshima Electric Railway)', null, 35.31684, 139.53573, '4-2-28, Hase, Kamakura, Kanagawa Prefecture 248-0016, Japan', null, null, null, '{}', '{"https://www.kotoku-in.jp/en/index.php","https://en.wikipedia.org/wiki/Kotoku-in"}', '{"name": "https://www.kotoku-in.jp/en/index.php", "description": "https://en.wikipedia.org/wiki/Kotoku-in", "hours": "https://www.kotoku-in.jp/en/index.php", "station": "https://www.kotoku-in.jp/en/index.php", "lat": "https://en.wikipedia.org/wiki/Kotoku-in", "lng": "https://en.wikipedia.org/wiki/Kotoku-in", "address": "https://www.kotoku-in.jp/en/index.php"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:kamakura:tsurugaoka-hachimangu', 'Kanto', 'Kanagawa', 'Kamakura', 'JP', 'Tsurugaoka Hachimangu', 'Shrine', 'Founded in 1063 and relocated to its current site in 1180 by the shogun Minamoto no Yoritomo, this historic Shinto shrine serves as the cultural center of Kamakura.', '[{"text": "The main approach is Wakamiya Ōji, a straight boulevard featuring three grand torii gates and a raised cherry-blossom path.", "source_url": "https://en.wikipedia.org/wiki/Tsurugaoka_Hachimang%C5%AB"}, {"text": "The shrine grounds host the Kamakura Bunkakan Tsurugaoka Museum and the Genpei Ponds with their historic lotus plants.", "source_url": "https://en.wikipedia.org/wiki/Tsurugaoka_Hachimang%C5%AB"}]'::jsonb, '6:00 AM - 8:00 PM', 'known', 'Kamakura Station (JR Yokosuka Line / Shonan-Shinjuku Line / Enoshima Electric Railway)', null, 35.324722, 139.555833, '2-1-31, Yukinoshita, Kamakura-shi, Kanagawa 248-8588, Japan', null, null, null, '{}', '{"https://www.hachimangu.or.jp/en/access/","https://en.wikipedia.org/wiki/Tsurugaoka_Hachimang%C5%AB"}', '{"name": "https://www.hachimangu.or.jp/en/access/", "description": "https://en.wikipedia.org/wiki/Tsurugaoka_Hachimang%C5%AB", "hours": "https://www.hachimangu.or.jp/en/access/", "station": "https://www.hachimangu.or.jp/en/access/", "lat": "https://en.wikipedia.org/wiki/Tsurugaoka_Hachimang%C5%AB", "lng": "https://en.wikipedia.org/wiki/Tsurugaoka_Hachimang%C5%AB", "address": "https://www.hachimangu.or.jp/en/access/"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:kamakura:hase-dera-kamakura', 'Kanto', 'Kanagawa', 'Kamakura', 'JP', 'Hase-dera (Kamakura)', 'Temple', 'A Jodo-shu Buddhist temple built on a mountain slope, famed for its nine-meter-tall wooden statue of Eleven-Headed Kannon and scenic views of Yuigahama beach.', '[{"text": "Explore the Benten-kutsu cave, which features a low-ceilinged winding tunnel filled with chiseled statues of Benzaiten.", "source_url": "https://en.wikipedia.org/wiki/Hase-dera_(Kamakura)"}, {"text": "During June and July, the temple''s Hydrangea Path features blooming flowers and panoramic vistas of Sagami Bay.", "source_url": "https://en.wikipedia.org/wiki/Hase-dera_(Kamakura)"}]'::jsonb, '8:00 AM - 4:30 PM (regular season, grounds close at 5:00 PM), 8:00 AM - 5:00 PM (April to June, grounds close at 5:30 PM)', 'known', 'Hase Station (Enoshima Electric Railway)', null, 35.3125, 139.533056, '3-11-2 Hase, Kamakura-shi, Kanagawa Prefecture 248-0016, Japan', null, null, null, '{}', '{"https://www.hasedera.jp/guide/","https://en.wikipedia.org/wiki/Hase-dera_(Kamakura)"}', '{"name": "https://www.hasedera.jp/guide/", "description": "https://en.wikipedia.org/wiki/Hase-dera_(Kamakura)", "hours": "https://www.hasedera.jp/guide/", "station": "https://en.wikipedia.org/wiki/Hase-dera_(Kamakura)", "lat": "https://en.wikipedia.org/wiki/Hase-dera_(Kamakura)", "lng": "https://en.wikipedia.org/wiki/Hase-dera_(Kamakura)", "address": "https://www.hasedera.jp/guide/"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:kamakura:hokoku-ji', 'Kanto', 'Kanagawa', 'Kamakura', 'JP', 'Hokoku-ji', 'Temple', 'A historic Zen Buddhist temple of the Rinzai sect established in 1334, widely celebrated for its magnificent grove of approximately 2,000 towering moso bamboo trees.', '[{"text": "Purchase an optional matcha ticket at the entrance to enjoy hot tea and sweets at the Kyukohan tea house overlooking the bamboo grove.", "source_url": "https://houkokuji.or.jp/guide/"}, {"text": "Tripods, monopods, and selfie sticks are strictly prohibited on the temple grounds.", "source_url": "https://visit.trip-kamakura.com/things-to-do/hokokuji-temple/"}]'::jsonb, '9:00 AM - 4:00 PM', 'known', 'Kamakura Station (JR Yokosuka Line / Shonan-Shinjuku Line / Enoshima Electric Railway)', null, 35.32, 139.5693, '2-7-4 Jomyoji, Kamakura-shi, Kanagawa Prefecture 248-0003, Japan', null, null, null, '{}', '{"https://houkokuji.or.jp/guide/","https://en.wikipedia.org/wiki/H%C5%8Dkoku-ji","https://visit.trip-kamakura.com/things-to-do/hokokuji-temple/"}', '{"name": "https://houkokuji.or.jp/guide/", "description": "https://en.wikipedia.org/wiki/H%C5%8Dkoku-ji", "hours": "https://houkokuji.or.jp/guide/", "station": "https://houkokuji.or.jp/", "lat": "https://en.wikipedia.org/wiki/H%C5%8Dkoku-ji", "lng": "https://en.wikipedia.org/wiki/H%C5%8Dkoku-ji", "address": "https://houkokuji.or.jp/guide/"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:hakone:owakudani', 'Kanto', 'Kanagawa', 'Hakone', 'JP', 'Owakudani', 'Volcanic Valley', 'A volcanic valley in Hakone, Kanagawa Prefecture, formed approximately 3,000 years ago during the eruption of the Hakone volcano. It is a popular tourist attraction known for its active sulfur vents, hot springs, and scenic views of Mount Fuji.', '[{"text": "Try the local black eggs (kuro-tamago) which are hard-boiled in the sulfurous hot spring waters, turning their shells black and rumored to extend your life by seven years.", "source_url": "https://en.wikipedia.org/wiki/Owakudani"}, {"text": "Due to active volcanic gas emissions, visitors with respiratory conditions, heart disease, pacemakers, or who are pregnant are cautioned against entering the valley.", "source_url": "https://en.wikipedia.org/wiki/Owakudani"}]'::jsonb, 'unknown', 'unknown', 'Ōwakudani Station', null, 35.241916, 139.020667, 'Hakone, Kanagawa Prefecture, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Owakudani","https://owakudani.com/","https://www.wikidata.org/wiki/Q1134429"}', '{"name": "https://en.wikipedia.org/wiki/Owakudani", "description": "https://en.wikipedia.org/wiki/Owakudani", "category": "https://www.wikidata.org/wiki/Q1134429", "station": "https://en.wikipedia.org/wiki/Owakudani", "lat": "https://www.wikidata.org/wiki/Q1134429", "lng": "https://www.wikidata.org/wiki/Q1134429", "address": "https://en.wikipedia.org/wiki/Owakudani"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:hakone:hakone-shrine', 'Kanto', 'Kanagawa', 'Hakone', 'JP', 'Hakone Shrine', 'Shinto Shrine', 'A historic Shinto shrine located on the shores of Lake Ashi in Hakone, Kanagawa Prefecture, originally founded in 757 during the reign of Emperor Kosho. It is famous for its iconic vermilion torii gate that stands directly in the waters of the lake.', '[{"text": "Visit the shrine''s small museum to view historic treasures, including five items designated as national Important Cultural Properties.", "source_url": "https://en.wikipedia.org/wiki/Hakone_Shrine"}, {"text": "Participate in or witness the shrine''s main annual festival, which takes place on August 1st.", "source_url": "https://en.wikipedia.org/wiki/Hakone_Shrine"}]'::jsonb, 'unknown', 'unknown', 'unknown', null, 35.203889, 139.025556, 'Hakone, Kanagawa Prefecture, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Hakone_Shrine","https://hakonejinja.or.jp/","https://www.wikidata.org/wiki/Q705310"}', '{"name": "https://en.wikipedia.org/wiki/Hakone_Shrine", "description": "https://en.wikipedia.org/wiki/Hakone_Shrine", "category": "https://www.wikidata.org/wiki/Q705310", "lat": "https://www.wikidata.org/wiki/Q705310", "lng": "https://www.wikidata.org/wiki/Q705310", "address": "https://en.wikipedia.org/wiki/Hakone_Shrine"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:hakone:hakone-open-air-museum', 'Kanto', 'Kanagawa', 'Hakone', 'JP', 'Hakone Open-Air Museum', 'Art Museum', 'Japan''s first open-air museum, opened in 1969, featuring a sculpture park and gardens with permanent displays of around 120 sculptural works. The museum hosts over 1,000 pieces in total, including extensive collections by artists like Pablo Picasso and Henry Moore.', '[{"text": "Explore the Picasso Pavilion, an exhibition hall dedicated to Spanish artist Pablo Picasso that contains about 300 of his works.", "source_url": "https://en.wikipedia.org/wiki/Hakone_Open-Air_Museum"}, {"text": "Take a moment to relax your feet at the museum''s naturally fed hot spring (onsen) footbath available for guests.", "source_url": "https://en.wikipedia.org/wiki/Hakone_Open-Air_Museum"}]'::jsonb, 'unknown', 'unknown', 'Chokoku-no-Mori Station', null, 35.244719, 139.051506, 'Hakone, Kanagawa Prefecture, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Hakone_Open-Air_Museum","https://www.hakone-oam.or.jp/","https://www.wikidata.org/wiki/Q1134422"}', '{"name": "https://en.wikipedia.org/wiki/Hakone_Open-Air_Museum", "description": "https://en.wikipedia.org/wiki/Hakone_Open-Air_Museum", "category": "https://www.wikidata.org/wiki/Q1134422", "station": "https://en.wikipedia.org/wiki/Hakone_Open-Air_Museum", "lat": "https://www.wikidata.org/wiki/Q1134422", "lng": "https://www.wikidata.org/wiki/Q1134422", "address": "https://en.wikipedia.org/wiki/Hakone_Open-Air_Museum"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:hakone:hakone-ropeway', 'Kanto', 'Kanagawa', 'Hakone', 'JP', 'Hakone Ropeway', 'Aerial Lift', 'An aerial funitel line in Hakone, Kanagawa Prefecture, linking Sounzan and Togendai via Owakudani. It forms a key part of the sightseeing route between Odawara and Lake Ashi, offering passengers scenic mountain views.', '[{"text": "Use the ropeway as a scenic connection between Sounzan and Togendai to enjoy views of Mount Fuji on clear days.", "source_url": "https://en.wikipedia.org/wiki/Hakone_Ropeway"}, {"text": "Be aware that the ropeway has been operated as a funitel system since 2002/2007, consisting of two distinct connected sections.", "source_url": "https://en.wikipedia.org/wiki/Hakone_Ropeway"}]'::jsonb, 'unknown', 'unknown', 'Sōunzan Station', null, 35.244361, 139.019111, 'Hakone, Kanagawa Prefecture, Japan', null, null, null, '{}', '{"https://en.wikipedia.org/wiki/Hakone_Ropeway","https://www.hakonenavi.jp/international/en/","https://www.wikidata.org/wiki/Q1049195"}', '{"name": "https://en.wikipedia.org/wiki/Hakone_Ropeway", "description": "https://en.wikipedia.org/wiki/Hakone_Ropeway", "category": "https://www.wikidata.org/wiki/Q1049195", "station": "https://en.wikipedia.org/wiki/Hakone_Ropeway", "lat": "https://www.wikidata.org/wiki/Q1049195", "lng": "https://www.wikidata.org/wiki/Q1049195", "address": "https://en.wikipedia.org/wiki/Hakone_Ropeway"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:yokohama:sankeien-garden', 'Kanto', 'Kanagawa', 'Yokohama', 'JP', 'Sankeien Garden', 'Garden', 'A sprawling traditional Japanese garden covering over 175,000 square meters, featuring historical buildings relocated from across Japan including Kyoto and Kamakura.', '[{"text": "The garden contains ten historical buildings designated as Important Cultural Properties by the Japanese government.", "source_url": "https://en.wikipedia.org/wiki/Sankeien"}, {"text": "Volunteer English-speaking guides are available free of charge to lead tours of the garden.", "source_url": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=87"}]'::jsonb, '9:00am-5:00pm (Last entry 4:30pm). Closed: 12/26-12/31.', 'known', 'From Negishi Station, take the municipal bus (Route 58, 99, or 101) to the ''Honmoku'' bus stop and walk 10 minutes; or from Yokohama Station, take Route 8 or 148 to ''Honmoku Sankeien Mae'' and walk 5 minutes.', null, 35.41695, 139.660042, '58-1, Honmoku Sannotani, Naka-ku, Yokohama, 231-0824', null, null, 'https://upload.wikimedia.org/wikipedia/commons/6/67/Sankeien_Rinshukaku_and_Teisha_Bridge.jpg', '{}', '{"https://www.yokohamajapan.com/things-to-do/detail.php?bbid=87","https://en.wikipedia.org/wiki/Sankeien","https://commons.wikimedia.org/wiki/File:Sankeien_Rinshukaku_and_Teisha_Bridge.jpg"}', '{"name": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=87", "category": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=87", "description": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=87", "hours": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=87", "station": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=87", "lat": "https://en.wikipedia.org/wiki/Sankeien", "lng": "https://en.wikipedia.org/wiki/Sankeien", "address": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=87", "image_url": "https://commons.wikimedia.org/wiki/File:Sankeien_Rinshukaku_and_Teisha_Bridge.jpg"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:yokohama:yokohama-red-brick-warehouse', 'Kanto', 'Kanagawa', 'Yokohama', 'JP', 'Yokohama Red Brick Warehouse', 'Sights & Landmarks', 'A historic customs inspection complex constructed in the early 1910s, now operating as a popular dining, shopping, and cultural events venue by the port.', '[{"text": "The complex is divided into Building 1, which hosts cultural events and art exhibitions, and Building 2, which contains numerous shops and restaurants.", "source_url": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=184"}, {"text": "Every winter, an outdoor ice skating rink decorated with light displays is set up in the plaza.", "source_url": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=184"}]'::jsonb, '1st Building: 10:00am - 7:00pm. 2nd Building: 11:00am - 8:00pm. Cafe and restaurant hours vary.', 'known', 'A 6-minute walk from Nihon Odori Station or Bashamichi Station; or a 15-minute walk from Kannai Station or Sakuragicho Station.', null, 35.452222222222225, 139.64277777777778, '1-1-2 Shinko, Naka-ku, Yokohama, 231-0001', null, null, 'https://upload.wikimedia.org/wikipedia/commons/9/92/Akarenga_Yokohama_2012.jpg', '{}', '{"https://www.yokohamajapan.com/things-to-do/detail.php?bbid=184","https://en.wikipedia.org/wiki/Yokohama_Red_Brick_Warehouse","https://commons.wikimedia.org/wiki/File:Akarenga_Yokohama_2012.jpg"}', '{"name": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=184", "category": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=184", "description": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=184", "hours": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=184", "station": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=184", "lat": "https://en.wikipedia.org/wiki/Yokohama_Red_Brick_Warehouse", "lng": "https://en.wikipedia.org/wiki/Yokohama_Red_Brick_Warehouse", "address": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=184", "image_url": "https://commons.wikimedia.org/wiki/File:Akarenga_Yokohama_2012.jpg"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:yokohama:cupnoodles-museum-yokohama', 'Kanto', 'Kanagawa', 'Yokohama', 'JP', 'CUPNOODLES MUSEUM YOKOHAMA', 'Museum', 'An interactive museum dedicated to instant ramen and its inventor Momofuku Ando, where visitors can design their own custom cup noodles.', '[{"text": "Attraction fees are required separately for hands-on activities such as the Chicken Ramen Factory and My CUPNOODLES Factory.", "source_url": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=756"}, {"text": "An internet connection and credit card are required to purchase tickets online, which became available in February 2025.", "source_url": "https://www.cupnoodles-museum.jp/en/yokohama/"}]'::jsonb, '10:00am-6:00 pm', 'known', 'Walk from Sakuragicho Station (JR Keihin-Tohoku Negishi Line / Yokohama Municipal Subway) or Minatomirai Station (Minatomirai Line).', null, 35.45547222222223, 139.6388611111111, '2-3-4 Shinko, Naka-ku, Yokohama', null, null, 'https://upload.wikimedia.org/wikipedia/commons/6/6d/Cupnoodles-Museum-Yokohama.jpg', '{}', '{"https://www.yokohamajapan.com/things-to-do/detail.php?bbid=756","https://en.wikipedia.org/wiki/CupNoodles_Museum_Yokohama","https://www.cupnoodles-museum.jp/en/yokohama/","https://commons.wikimedia.org/wiki/File:Cupnoodles-Museum-Yokohama.jpg"}', '{"name": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=756", "category": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=756", "description": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=756", "hours": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=756", "station": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=756", "lat": "https://en.wikipedia.org/wiki/CupNoodles_Museum_Yokohama", "lng": "https://en.wikipedia.org/wiki/CupNoodles_Museum_Yokohama", "address": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=756", "image_url": "https://commons.wikimedia.org/wiki/File:Cupnoodles-Museum-Yokohama.jpg"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:kanagawa:yokohama:yokohama-landmark-tower-sky-garden', 'Kanto', 'Kanagawa', 'Yokohama', 'JP', 'Yokohama Landmark Tower Sky Garden', 'Sights & Landmarks', 'A 360-degree observation deck located on the 69th floor of Yokohama Landmark Tower, offering expansive views of Yokohama, Tokyo, and Mount Fuji.', '[{"text": "The tower features some of the world''s fastest elevators, which ascend to the 69th floor in approximately 40 seconds.", "source_url": "https://en.wikipedia.org/wiki/Yokohama_Landmark_Tower"}, {"text": "Due to large-scale renovations, the Sky Garden will temporarily suspend operations starting December 31, 2025, and is scheduled to reopen in or after 2028.", "source_url": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=183"}]'::jsonb, '10:00am-9:00 pm. Saturdays: 10:00 am-10:00pm.', 'known', 'Walk from Sakuragicho Station (JR Keihin-Tohoku Negishi Line / Yokohama Municipal Subway) or Minatomirai Station (Minatomirai Line).', null, 35.45472222222222, 139.63166666666666, '2-2-1 Minatomirai, Nishi-ku, Yokohama', null, null, 'https://upload.wikimedia.org/wikipedia/commons/0/03/Yokohama_Landmark_Tower_201507.JPG', '{}', '{"https://www.yokohamajapan.com/things-to-do/detail.php?bbid=183","https://en.wikipedia.org/wiki/Yokohama_Landmark_Tower","https://commons.wikimedia.org/wiki/File:Yokohama_Landmark_Tower_201507.JPG"}', '{"name": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=183", "category": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=183", "description": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=183", "hours": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=183", "station": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=183", "lat": "https://en.wikipedia.org/wiki/Yokohama_Landmark_Tower", "lng": "https://en.wikipedia.org/wiki/Yokohama_Landmark_Tower", "address": "https://www.yokohamajapan.com/things-to-do/detail.php?bbid=183", "image_url": "https://commons.wikimedia.org/wiki/File:Yokohama_Landmark_Tower_201507.JPG"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:chiba:narita:naritasan-shinshoji-temple', 'Kanto', 'Chiba', 'Narita', 'JP', 'Naritasan Shinshoji Temple', 'Buddhist Temple', 'A prominent and historic Shingon Buddhist temple complex founded in 940 to commemorate a military victory. It is dedicated to Fudo Myoo, a Buddhist deity of unmovable wisdom, and is renowned for its daily Goma sacred fire rituals.', '[{"text": "Witness the Goma sacred fire ritual which is performed several times daily in the Great Main Hall.", "source_url": "https://en.wikipedia.org/wiki/Narita-san"}, {"text": "The temple grounds feature historic structures designated as National Important Cultural Properties, including a 25-meter high pagoda built in 1712.", "source_url": "https://en.wikipedia.org/wiki/Narita-san"}]'::jsonb, 'unknown', 'unknown', 'JR Narita Station / Keisei Narita Station', null, 35.786095, 140.318297, '千葉県成田市成田1', null, null, 'https://upload.wikimedia.org/wikipedia/commons/2/25/120803_Narita-san_Shinsho-ji_Narita_Chiba_pref_Japan01n.jpg', '{}', '{"https://www.nrtk.jp/mypage/00156.html","https://en.wikipedia.org/wiki/Narita-san"}', '{"name": "https://www.nrtk.jp/mypage/00156.html", "description": "https://www.nrtk.jp/mypage/00156.html", "lat": "https://www.nrtk.jp/mypage/00156.html", "lng": "https://www.nrtk.jp/mypage/00156.html", "address": "https://www.nrtk.jp/mypage/00156.html", "station": "https://www.nrtk.jp/mypage/00156.html"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, null),
  ('jp-kanto-pilot-2026-07-14', 'name:chiba:narita:naritasan-park', 'Kanto', 'Chiba', 'Narita', 'JP', 'Naritasan Park', 'Park', 'A massive traditional Japanese park and garden located adjacent to Naritasan Shinshoji Temple. It is celebrated for its scenic walking paths, beautiful plum blossoms in early spring, and vibrant autumn foliage.', '[{"text": "Visit in early spring to view the plum blossoms (ume) or in late autumn for the stunning colorful leaves.", "source_url": "https://en.wikipedia.org/wiki/Narita-san"}]'::jsonb, 'unknown', 'unknown', 'JR Narita Station / Keisei Narita Station', null, 35.7866845, 140.3210126, null, null, null, 'https://upload.wikimedia.org/wikipedia/commons/e/e7/IMAG1509_%2828154414491%29.jpg', '{}', '{"https://en.wikipedia.org/wiki/Narita-san","https://www.wikidata.org/wiki/Q136504677"}', '{"name": "https://en.wikipedia.org/wiki/Narita-san", "description": "https://en.wikipedia.org/wiki/Narita-san", "lat": "https://www.wikidata.org/wiki/Q136504677", "lng": "https://www.wikidata.org/wiki/Q136504677", "station": "https://en.wikipedia.org/wiki/Narita-san"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, null),
  ('jp-kanto-pilot-2026-07-14', 'name:chiba:narita:narita-city-sakuranoyama-park', 'Kanto', 'Chiba', 'Narita', 'JP', 'Narita City Sakuranoyama Park', 'Park', 'A popular plane-spotting hill park situated near the northern edge of Narita International Airport''s runway. It offers a dramatic view of ascending and descending flights, combined with a beautiful display of around 500 cherry trees.', '[{"text": "The park is selected as one of the ''100 views of Chiba'' and is a highly popular filming location for television shows.", "source_url": "https://www.nrtk.jp/enjoy/attraction/sakuranoyama.html"}, {"text": "Stop by the on-site ''Sora no Eki Sakura-館'' to purchase fresh local vegetables and unique airport-themed souvenirs.", "source_url": "https://www.nrtk.jp/enjoy/attraction/sakuranoyama.html"}]'::jsonb, 'unknown', 'unknown', 'JR Narita Station / Keisei Narita Station', null, 35.774905, 140.361195, '千葉県成田市駒井野1338-1', null, null, 'https://upload.wikimedia.org/wikipedia/commons/1/1e/Sakuranoyama_Park.JPG', '{}', '{"https://www.nrtk.jp/mypage/00153.html","https://www.nrtk.jp/enjoy/attraction/sakuranoyama.html"}', '{"name": "https://www.nrtk.jp/mypage/00153.html", "description": "https://www.nrtk.jp/enjoy/attraction/sakuranoyama.html", "lat": "https://www.nrtk.jp/mypage/00153.html", "lng": "https://www.nrtk.jp/mypage/00153.html", "address": "https://www.nrtk.jp/mypage/00153.html", "station": "https://www.nrtk.jp/enjoy/attraction/sakuranoyama.html"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, null),
  ('jp-kanto-pilot-2026-07-14', 'name:chiba:choshi:inubosaki-lighthouse', 'Kanto', 'Chiba', 'Choshi', 'JP', 'Inubosaki Lighthouse', 'Lighthouse', 'A historic Western-style lighthouse located on Cape Inubō in Choshi, Chiba Prefecture. Built in 1874 by British engineer Richard Henry Brunton, it is constructed from Japan''s first domestically produced red bricks.', '[{"text": "Visitors can climb 99 steps to the top of the lighthouse for a panoramic view of the Pacific Ocean.", "source_url": "https://ja.wikipedia.org/wiki/%E7%8A%AC%E5%90%A0%E5%9F%BC%E7%81%AF%E5%8F%B0"}, {"text": "There is a rare white round-shaped postbox installed at the lighthouse, which is a popular spot for couples.", "source_url": "https://ja.wikipedia.org/wiki/%E7%8A%AC%E5%90%A0%E5%9F%BC%E7%81%AF%E5%8F%B0"}, {"text": "Cape Inubō can be reached by a 10-minute walk from Inuboh Station on the Chōshi Electric Railway Line.", "source_url": "https://en.wikipedia.org/wiki/Cape_Inub%C5%8D"}]'::jsonb, 'unknown', 'unknown', 'Inuboh Station', null, 35.70444, 140.86472, '9576 Inubosaki, Choshi, Chiba, Japan', null, null, null, '{}', '{"https://www.city.choshi.chiba.jp/","https://www.tokokai.org/","https://en.wikipedia.org/wiki/Inub%C5%8Dsaki_Lighthouse","https://ja.wikipedia.org/wiki/%E7%8A%AC%E5%90%A0%E5%9F%BC%E7%81%AF%E5%8F%B0","https://en.wikipedia.org/wiki/Cape_Inub%C5%8D"}', '{"name": "https://en.wikipedia.org/wiki/Inub%C5%8Dsaki_Lighthouse", "category": "https://en.wikipedia.org/wiki/Inub%C5%8Dsaki_Lighthouse", "description": "https://en.wikipedia.org/wiki/Inub%C5%8Dsaki_Lighthouse", "station": "https://en.wikipedia.org/wiki/Cape_Inub%C5%8D", "lat": "https://en.wikipedia.org/wiki/Inub%C5%8Dsaki_Lighthouse", "lng": "https://en.wikipedia.org/wiki/Inub%C5%8Dsaki_Lighthouse", "address": "https://ja.wikipedia.org/wiki/%E7%8A%AC%E5%90%A0%E5%9F%BC%E7%81%AF%E5%8F%B0"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:chiba:choshi:ch-shi-electric-railway', 'Kanto', 'Chiba', 'Choshi', 'JP', 'Chōshi Electric Railway', 'Heritage Railway', 'A historic 6.4-kilometer private railway line that operates between Choshi and Tokawa stations in Chiba Prefecture. Opened in 1923, the railway is famous for its retro charm and local community support.', '[{"text": "The railway produced its own horror comedy film titled ''Don''t Stop the Train! – The Cursed 6.4km –'' in 2019 to help support the line.", "source_url": "https://en.wikipedia.org/wiki/Ch%C5%8Dshi_Electric_Railway"}, {"text": "In response to the COVID-19 pandemic, the railway launched a popular YouTube channel called Gekitsura Channel featuring various local staff.", "source_url": "https://en.wikipedia.org/wiki/Ch%C5%8Dshi_Electric_Railway"}, {"text": "The line was branded as the ''Inubō Gakeppuchi Line'' as part of its Gakeppuchi Project tourism campaign from April 2025.", "source_url": "https://en.wikipedia.org/wiki/Ch%C5%8Dshi_Electric_Railway"}]'::jsonb, 'unknown', 'unknown', 'Choshi Station', null, 35.7292, 140.8353, 'Nakanochō, Chōshi, Chiba, Japan', null, null, null, '{}', '{"https://www.choshi-dentetsu.jp/","https://www.choshi-dentetsu.jp/timetable/","https://en.wikipedia.org/wiki/Ch%C5%8Dshi_Electric_Railway","https://en.wikipedia.org/wiki/Nakanocho_Station"}', '{"name": "https://en.wikipedia.org/wiki/Ch%C5%8Dshi_Electric_Railway", "category": "https://en.wikipedia.org/wiki/Ch%C5%8Dshi_Electric_Railway", "description": "https://en.wikipedia.org/wiki/Ch%C5%8Dshi_Electric_Railway", "station": "https://en.wikipedia.org/wiki/Ch%C5%8Dshi_Electric_Railway", "lat": "https://en.wikipedia.org/wiki/Nakanocho_Station", "lng": "https://en.wikipedia.org/wiki/Nakanocho_Station", "address": "https://en.wikipedia.org/wiki/Nakanocho_Station"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:chiba:choshi:byobugaura-cliffs', 'Kanto', 'Chiba', 'Choshi', 'JP', 'Byobugaura Cliffs', 'Scenic Cliff', 'A dramatic 10-kilometer stretch of coastal marine cliffs overlooking the Pacific Ocean between Choshi and Asahi. Often called the ''Dover of the East'' for its likeness to England''s white cliffs, it showcases prominent geological layers.', '[{"text": "Most sections of the cliffs are off-limits due to danger and erosion, but visitors can get a close view via a designated walking path near Choshi Marina.", "source_url": "https://ja.wikipedia.org/wiki/%E5%B1%8F%E9%A2%A8%E3%83%B6%E6%B5%A6"}, {"text": "The cliffs can also be viewed from the Hill of the Round Earth Observatory (Chikyu no Maruku Mieru Oka Tenbokan).", "source_url": "https://ja.wikipedia.org/wiki/%E5%B1%8F%E9%A2%A8%E3%83%B6%E6%B5%A6"}, {"text": "Byobugaura is a popular filming location for suspense dramas, movies, and music videos.", "source_url": "https://ja.wikipedia.org/wiki/%E5%B1%8F%E9%A2%A8%E3%83%B6%E6%B5%A6"}]'::jsonb, 'unknown', 'unknown', null, null, 35.70111, 140.80389, 'Naaraicho, Choshi, Chiba, Japan', null, null, null, '{}', '{"https://www.city.choshi.chiba.jp/","https://en.wikipedia.org/wiki/By%C5%8Dbugaura","https://ja.wikipedia.org/wiki/%E5%B1%8F%E9%A2%A8%E3%83%B6%E6%B5%A6"}', '{"name": "https://en.wikipedia.org/wiki/By%C5%8Dbugaura", "category": "https://en.wikipedia.org/wiki/By%C5%8Dbugaura", "description": "https://en.wikipedia.org/wiki/By%C5%8Dbugaura", "lat": "https://ja.wikipedia.org/wiki/%E5%B1%8F%E9%A2%A8%E3%83%B6%E6%B5%A6", "lng": "https://ja.wikipedia.org/wiki/%E5%B1%8F%E9%A2%A8%E3%83%B6%E6%B5%A6", "address": "https://ja.wikipedia.org/wiki/%E5%B1%8F%E9%A2%A8%E3%83%B6%E6%B5%A6"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z'),
  ('jp-kanto-pilot-2026-07-14', 'name:chiba:katori:katori-jingu', 'Kanto', 'Chiba', 'Katori', 'JP', 'Katori Jingu', 'Shinto Shrine', 'A highly prestigious Shinto shrine located in Katori, Chiba Prefecture, dedicated to the martial deity Futsunushi-no-Mikoto. It serves as the head shrine of approximately 400 Katori shrines across Japan.', '[{"text": "It was one of only three shrines designated with the prestigious title of ''Jingu'' in the Heian-period Engishiki records, along with Ise Jingu and Kashima Jingu.", "source_url": "https://en.wikipedia.org/wiki/Katori_Jing%C5%AB"}, {"text": "Many of the main structures, including the honden, romon, and old haiden, date from a major reconstruction in 1700 by the Tokugawa Shogunate.", "source_url": "https://ja.wikipedia.org/wiki/%E9%A6%99%E5%8F%96%E7%A5%9E%E5%AE%AE"}, {"text": "The shrine was historically revered by the samurai class as a guardian of martial arts.", "source_url": "https://en.wikipedia.org/wiki/Katori_Jing%C5%AB"}]'::jsonb, 'unknown', 'unknown', null, null, 35.885556, 140.528333, '1697 Katori, Katori, Chiba, Japan', null, null, null, '{}', '{"https://katori-jingu.or.jp/","https://en.wikipedia.org/wiki/Katori_Jing%C5%AB","https://ja.wikipedia.org/wiki/%E9%A6%99%E5%8F%96%E7%A5%9E%E5%AE%AE"}', '{"name": "https://en.wikipedia.org/wiki/Katori_Jing%C5%AB", "category": "https://en.wikipedia.org/wiki/Katori_Jing%C5%AB", "description": "https://en.wikipedia.org/wiki/Katori_Jing%C5%AB", "lat": "https://en.wikipedia.org/wiki/Katori_Jing%C5%AB", "lng": "https://en.wikipedia.org/wiki/Katori_Jing%C5%AB", "address": "https://ja.wikipedia.org/wiki/%E9%A6%99%E5%8F%96%E7%A5%9E%E5%AE%AE"}'::jsonb, null, 'gemini-3.5-flash', 'approved', '[]'::jsonb, true, null, '2026-07-14T23:11:55.588178Z')
